  pathToFileURL(join(browserPluginRoot, "scripts", "browser-client.mjs")).href
);
await setupBrowserRuntime({ globals: globalThis });

const browser = await agent.browsers.getForUrl("https://www.baidu.com/");
const list = await browser.tabs.list();
const info = list.find((t) => (t.url || "").includes("wd=%E5%8F%A4%E4%BB%8A%E5%A5%BD%E8%AF%BE"));
if (!info) throw new Error("baidu tab not found: " + JSON.stringify(list));
